#!/usr/bin/env python3
"""Deliver only the context generated by a real Lacquer sync."""
import json
import os
from pathlib import Path

root = Path(os.environ["CLAUDE_PLUGIN_ROOT"])
print(json.dumps({"hookSpecificOutput": {
    "hookEventName": "SessionStart",
    "additionalContext": (root / "rules.md").read_text(),
}}))
